import seedData from "@/content/generated/search-tips-seed.json";

/**
 * Large rotating SSOT tip pool for the header idle search-bar animation.
 *
 * Rules:
 *  - Every single tip is derived strictly from committed SSOT data in `content/generated/search-tips-seed.json`
 *    (regenerated by `scripts/generate-content.ts` from `data/*.json`).
 *  - Never invent ZIP codes or bank sort codes in tip strings; use verified place/bank/LGA/topic names
 *    and real hub intents.
 *  - Case-insensitively deduplicated and capped to concise single-line length so tips read cleanly on mobile.
 *  - Interleaved across 4 topic buckets so each 3-tip burst before the 5s cool-off spans distinct verticals
 *    rather than repeating one category.
 */

type TipsSeed = {
  banks: string[];
  airports?: { city: string; iata: string }[];
  oilGasOperators?: string[];
  postalStates: string[];
  postalPlaces: string[];
  lgasByState: [string, string[]][];
  slangTerms: string[];
  psychTerms: string[];
  howtoTitles: { slug: string; title: string }[];
  recipes: string[];
  blueprints: string[];
  examInstitutions: string[];
  examGuides: string[];
  telecomNetworks: string[];
  learnTitles: string[];
  priceCities: string[];
  markets: string[];
};

const SEED = seedData as unknown as TipsSeed;

const HOWTO_NATURAL_INTENTS: Record<string, string> = {
  "nin-correction": "how can I change my name on my NIN?",
  "passport-renewal-2026": "Nigerian passport renewal fees & portal",
  "police-character-certificate": "how to get police character certificate",
  "cac-business-name": "CAC business name registration fee",
  "freelancer-tax-tin": "how freelancers get a TIN in Nigeria",
  "drivers-licence-frsc": "FRSC driver’s licence renewal fee",
  "prepaid-electricity-bands": "prepaid electricity Band A tariff check",
  "nbs-food-price-watch": "how to read NBS food price watch",
  "lasrra-lagos-residency": "LASRRA Lagos residency registration",
  "bvn-correction": "how to correct BVN name or date of birth",
  "birth-certificate-replacement": "NPC birth certificate attestation",
  "tax-clearance-certificate": "tax clearance certificate TCC steps",
};

function compactLabel(text: string, maxLen = 52): string {
  const clean = text.replace(/\s+/g, " ").trim();
  if (clean.length <= maxLen) return clean;
  // Trim cleanly at word boundary if a raw title is long
  const cut = clean.slice(0, maxLen);
  const lastSpace = cut.lastIndexOf(" ");
  return (lastSpace > 24 ? cut.slice(0, lastSpace) : cut).trim();
}

export type TipBuckets = {
  pricesAndRates: string[];
  codesPostalAndBanks: string[];
  guidesSlangAndTools: string[];
  geoStatesAndLgas: string[];
};

/**
 * Deterministically build the 4 deduplicated SSOT topic buckets.
 */
export function buildSearchTipBuckets(): TipBuckets {
  const seen = new Set<string>();
  const addUnique = (target: string[], raw: string) => {
    const clean = compactLabel(raw);
    if (!clean) return;
    const key = clean.toLowerCase();
    if (seen.has(key)) return;
    seen.add(key);
    target.push(clean);
  };

  const pricesAndRates: string[] = [];
  const codesPostalAndBanks: string[] = [];
  const guidesSlangAndTools: string[] = [];
  const geoStatesAndLgas: string[] = [];

  // 1) Rates, Fuel, Charts & City/Market Prices (real hubs + 4 live price cities + 7 live markets)
  for (const intent of [
    "prices of fuel today",
    "dollar rate?",
    "prices of rice",
    "what can 80k buy in Lagos?",
    "CBN official dollar rate",
    "parallel market dollar rate",
    "naira to dollar history",
    "depot petrol price today",
    "depot diesel price per litre",
    "cooking gas LPG price per kg",
    "50kg bag of rice price",
    "price of garri today",
    "price of brown beans",
    "crate of eggs price",
    "cost of living calculator",
  ]) {
    addUnique(pricesAndRates, intent);
  }
  const cityStaples = ["rice", "garri", "beans", "yam", "eggs"];
  for (const city of SEED.priceCities) {
    addUnique(pricesAndRates, `food prices in ${city}`);
    for (const staple of cityStaples) {
      addUnique(pricesAndRates, `price of ${staple} in ${city}`);
    }
  }
  for (const market of SEED.markets) {
    const shortMarket = market.replace(/\s+International\s+/i, " ");
    addUnique(pricesAndRates, `${shortMarket} prices`);
  }

  // 2) Bank Sort/USSD Codes & Postal/ZIP Codes (12 banks + 37 states + 76 verified postal places)
  // Place Umuahia & GTBank near front so deterministic tests see flagship examples early
  if (SEED.postalPlaces.includes("Umuahia")) {
    addUnique(codesPostalAndBanks, "what’s the ZIP of Umuahia?");
  }
  for (const bank of SEED.banks) {
    addUnique(codesPostalAndBanks, `${bank} sort code`);
    addUnique(codesPostalAndBanks, `${bank} USSD code`);
    addUnique(codesPostalAndBanks, `transfer code for ${bank}`);
  }
  for (const place of SEED.postalPlaces) {
    addUnique(codesPostalAndBanks, `what’s the ZIP of ${place}?`);
    addUnique(codesPostalAndBanks, `postal code for ${place}`);
  }
  for (const state of SEED.postalStates) {
    const stLabel = /abuja|fct/i.test(state) ? state : `${state} State`;
    addUnique(codesPostalAndBanks, `${stLabel} postal codes`);
  }

  // 3) GovHowTo, Slang/Trends, Tools, Cookbook, Hustle, Exam & Telecom
  addUnique(guidesSlangAndTools, "how can I change my name on my NIN?");
  for (const doc of SEED.howtoTitles) {
    const natural = HOWTO_NATURAL_INTENTS[doc.slug];
    if (natural) addUnique(guidesSlangAndTools, natural);
    addUnique(guidesSlangAndTools, doc.title.replace(/\s+2026\b/g, ""));
  }
  for (const term of SEED.slangTerms) {
    addUnique(guidesSlangAndTools, `what does ${term.toLowerCase()} mean?`);
    addUnique(guidesSlangAndTools, `${term} meaning in Naija slang`);
  }
  for (const psych of SEED.psychTerms) {
    addUnique(guidesSlangAndTools, psych.toLowerCase());
  }
  for (const recipe of SEED.recipes) {
    addUnique(guidesSlangAndTools, `cost to cook ${recipe}`);
  }
  for (const bp of SEED.blueprints) {
    addUnique(guidesSlangAndTools, `how to start ${bp}`);
  }
  for (const inst of SEED.examInstitutions) {
    addUnique(guidesSlangAndTools, `${inst} JAMB cut-off mark`);
  }
  for (const g of SEED.examGuides) {
    addUnique(guidesSlangAndTools, g);
  }
  for (const net of SEED.telecomNetworks) {
    addUnique(guidesSlangAndTools, `cheapest ${net} data plans`);
  }
  addUnique(guidesSlangAndTools, "night data plans in Nigeria");
  addUnique(guidesSlangAndTools, "airtime to cash rates");
  addUnique(guidesSlangAndTools, "generator fuel cost calculator");
  addUnique(guidesSlangAndTools, "solar inverter payback calculator");
  addUnique(guidesSlangAndTools, "Naija Price IQ & Slang quiz");
  for (const lt of SEED.learnTitles) {
    addUnique(guidesSlangAndTools, lt);
  }

  // 4) All 37 States + All 774 LGAs (`data/lgas.json`) + Verified Airports & Oil/Gas Operators
  addUnique(geoStatesAndLgas, "international airports in Nigeria");
  addUnique(geoStatesAndLgas, "major oil companies in Nigeria");
  for (const ap of SEED.airports ?? []) {
    if (ap.city) addUnique(geoStatesAndLgas, `${ap.city} airport code`);
  }
  for (const opName of SEED.oilGasOperators ?? []) {
    if (opName) addUnique(geoStatesAndLgas, `${opName} Nigeria`);
  }
  for (const [stateName, lgas] of SEED.lgasByState) {
    addUnique(geoStatesAndLgas, `LGAs in ${stateName}`);
    for (const lga of lgas) {
      const hasCouncil = /council|\blga\b/i.test(lga);
      addUnique(geoStatesAndLgas, hasCouncil ? `${lga}, ${stateName}` : `${lga} LGA`);
    }
  }

  return {
    pricesAndRates,
    codesPostalAndBanks,
    guidesSlangAndTools,
    geoStatesAndLgas,
  };
}

/**
 * Interleave the 4 buckets into a single flat non-repeating pool so consecutive
 * 3-tip bursts span distinct verticals instead of clustering in one dataset.
 */
export function interleaveTipBuckets(buckets: TipBuckets): string[] {
  const nonGeo = [
    buckets.pricesAndRates,
    buckets.codesPostalAndBanks,
    buckets.guidesSlangAndTools,
  ];
  const ptrs = [0, 0, 0];
  let nonGeoTurn = 0;

  const pullNonGeo = (): string | null => {
    for (let k = 0; k < nonGeo.length; k++) {
      const idx = (nonGeoTurn + k) % nonGeo.length;
      if (ptrs[idx] < nonGeo[idx].length) {
        const val = nonGeo[idx][ptrs[idx]++];
        nonGeoTurn = (idx + 1) % nonGeo.length;
        return val;
      }
    }
    return null;
  };

  const geo = buckets.geoStatesAndLgas;
  let geoPtr = 0;
  const out: string[] = [];

  // Build balanced triplets: [nonGeo A, nonGeo B (or geo), geo (or nonGeo C)]
  // First triplet gives 3 distinct non-geo flagship verticals right away; subsequent triplets mix 1-2 non-geo + 1-2 geo.
  const firstA = pullNonGeo();
  const firstB = pullNonGeo();
  const firstC = pullNonGeo();
  if (firstA) out.push(firstA);
  if (firstB) out.push(firstB);
  if (firstC) out.push(firstC);

  while (true) {
    const before = out.length;
    const ng1 = pullNonGeo();
    const ng2 = pullNonGeo();
    if (ng1) out.push(ng1);
    if (ng2) out.push(ng2);
    if (geoPtr < geo.length) out.push(geo[geoPtr++]);
    if (out.length === before) break;
  }

  return out;
}

function shuffleInPlace<T>(arr: T[], rng: () => number): T[] {
  for (let i = arr.length - 1; i > 0; i--) {
    const j = Math.floor(rng() * (i + 1));
    const tmp = arr[i];
    arr[i] = arr[j];
    arr[j] = tmp;
  }
  return arr;
}

/**
 * Deterministic full SSOT tip pool (>1,100 unique strings).
 */
export const IDLE_TIP_BUCKETS: TipBuckets = buildSearchTipBuckets();
export const IDLE_TIP_POOL: readonly string[] = interleaveTipBuckets(IDLE_TIP_BUCKETS);

/**
 * Create a freshly shuffled, bucket-interleaved permutation of all 1,100+ SSOT tips
 * so every browser load/refresh cycles through unique multi-vertical 3-tip bursts
 * without a fixed 10-item loop.
 */
export function createShuffledSearchTips(rng: () => number = Math.random): string[] {
  return interleaveTipBuckets({
    pricesAndRates: shuffleInPlace([...IDLE_TIP_BUCKETS.pricesAndRates], rng),
    codesPostalAndBanks: shuffleInPlace([...IDLE_TIP_BUCKETS.codesPostalAndBanks], rng),
    guidesSlangAndTools: shuffleInPlace([...IDLE_TIP_BUCKETS.guidesSlangAndTools], rng),
    geoStatesAndLgas: shuffleInPlace([...IDLE_TIP_BUCKETS.geoStatesAndLgas], rng),
  });
}
